/**
 * Sets whether to throw an exception when maxCount is reached.
 *
 * @param throwOnMaxCount true to throw an exception
 */
public void setThrowOnMaxCount(boolean throwOnMaxCount) {
    this.throwOnMaxCount = throwOnMaxCount;
}
